/* ============================================================
   INSTRUMENT 01: Layer explorer
   ============================================================ */
(function(){
  var L = {
    ger: { volt:"13,8 – 18 kV no terminal; elevação na SE da usina", dono:"Agentes de geração — estatais, privados, autoprodutores", oper:"O próprio agente, sob comando de despacho do ONS", reg:"ANEEL (outorga e fiscalização)", rem:"Venda de energia: contratos ACR/ACL, liquidação na CCEE", fat:"No preço da energia (TE no cativo; contrato no livre)", note:"A geração é o elo competitivo da cadeia: o preço se forma em leilão ou negociação — não em tarifa. É o território do Módulo 03 (tecnologias) e do Bloco 5 (mercado livre)." },
    tra: { volt:"230 – 765 kV em AC; ±600 / ±800 kV em DC", dono:"Transmissoras concessionárias (Eletrobras, ISA, Taesa, State Grid…)", oper:"ONS — operação centralizada da Rede Básica", reg:"ANEEL (leilões, RAP, fiscalização)", rem:"RAP por disponibilidade, definida em leilão de menor receita", fat:"Dentro do fio: TUST repassada via TUSD (Fio A)", note:"Monopólio natural com receita por disponibilidade: a linha ganha por existir e estar disponível, não por MWh transportado. Por isso transmissão virou o ativo de infraestrutura mais disputado do setor." },
    dis: { volt:"69 – 138 kV (AT) · 13,8 – 34,5 kV (MT) · 127 – 440 V (BT)", dono:"Distribuidoras concessionárias, com área de concessão exclusiva", oper:"A própria distribuidora, do seu centro de operação", reg:"ANEEL — REN 1.000/2021, PRODIST", rem:"TUSD (Fio B + repasses), homologada em revisão tarifária", fat:"TUSD: demanda (R$/kW) e energia (R$/MWh) no Grupo A", note:"Monopólio regulado por território: você não escolhe a distribuidora — escolhe, no máximo, quem vende a energia que passa pelo fio dela." },
    con: { volt:"Grupo A (2,3 a 230 kV) · Grupo B (baixa tensão)", dono:"Unidades consumidoras — a fábrica, o comércio, a casa", oper:"O consumidor, da fronteira para dentro", reg:"ANEEL (direitos e deveres — REN 1.000/2021)", rem:"—", fat:"É quem paga a soma: energia + fio + encargos + tributos", note:"Do ponto de conexão para dentro, ativos, perdas e riscos são do consumidor — por isso a subestação particular é item de auditoria do PQA." }
  };
  var pills = document.querySelectorAll("#i01-pills .pill");
  if(!pills.length) return;
  function show(key){
    var d = L[key];
    $id("i01-volt").textContent = d.volt;
    $id("i01-dono").textContent = d.dono;
    $id("i01-oper").textContent = d.oper;
    $id("i01-reg").textContent = d.reg;
    $id("i01-rem").textContent = d.rem;
    $id("i01-fat").textContent = d.fat;
    $id("i01-note").textContent = d.note;
  }
  pills.forEach(function(p){
    p.addEventListener("click", function(){
      pills.forEach(function(x){ x.classList.remove("active"); });
      p.classList.add("active");
      show(p.dataset.layer);
    });
  });
  show("ger");
})();

/* ============================================================
   INSTRUMENT 02: Transmission losses
   ============================================================ */
(function(){
  var rk = { 138: 0.16, 230: 0.09, 345: 0.045, 500: 0.022, 765: 0.011 };
  var p = $id("i02-p"), d = $id("i02-d"), v = $id("i02-v"), n = $id("i02-n");
  if(!p) return;
  var iOut = $id("i02-i"), lossOut = $id("i02-loss"), pctOut = $id("i02-pct"), yrOut = $id("i02-yr"), verd = $id("i02-verdict");
  function calc(){
    var P = parseFloat(p.value) || 0;
    var D = parseFloat(d.value) || 0;
    var V = parseFloat(v.value);
    var N = parseInt(n.value, 10);
    var I = P * 1e6 / (Math.sqrt(3) * V * 1000 * 0.95);
    var R = rk[V] * D;
    var loss = 3 * R * I * I / N / 1e6;
    var pct = P > 0 ? loss / P * 100 : 0;
    var lossShown = Math.min(loss, P);
    iOut.textContent = fb(I, 0) + " A";
    lossOut.textContent = fb(lossShown, 1) + " MW";
    pctOut.textContent = (pct > 100 ? "> 100" : fb(pct, 1)) + " %";
    var yr = lossShown * 8760 * 0.55 * 250;
    yrOut.textContent = "R$ " + fb(yr / 1e6, 1) + " mi";
    if(pct > 30){
      verd.className = "verdict danger";
      verd.innerHTML = "<b>Inviável.</b> Nessa configuração as perdas consomem " + (pct > 100 ? "mais de 100" : fb(pct, 0)) + "% do bloco — é por isso que essa linha não existe no mundo real. Suba o nível de tensão ou adicione circuitos e veja o quadrado da corrente trabalhar a seu favor.";
    } else if(pct > 8){
      verd.className = "verdict warn";
      verd.innerHTML = "<b>Caro.</b> Perdas de " + fb(pct, 1) + "% estão acima do razoável para um tronco. Em projeto real, subir a tensão ou adicionar um circuito tende a se pagar só com a energia que deixa de virar calor.";
    } else {
      verd.className = "verdict";
      verd.innerHTML = "<b>Dentro da faixa de engenharia.</b> " + fb(pct, 1) + "% de perdas para " + fb(P, 0) + " MW em " + fb(D, 0) + " km — este é o tipo de compromisso capital × perdas que desenhou os troncos reais do SIN.";
    }
  }
  bindIR("i02-p", calc);
  bindIR("i02-d", calc);
  v.addEventListener("input", calc);
  n.addEventListener("input", calc);
  calc();
})();

/* ============================================================
   INSTRUMENT 03: Transformation chain by consumer profile
   ============================================================ */
(function(){
  var chainEl = $id("i03-chain"), totalEl = $id("i03-total");
  if(!chainEl) return;
  var base = [
    { v: "13,8 → 500 kV", n: "SE elevadora da usina", l: 0.5 },
    { v: "500 kV", n: "Tronco de transmissão · Rede Básica", l: 1.8 },
    { v: "500 → 138 kV", n: "SE abaixadora regional", l: 0.4 }
  ];
  var prof = {
    a2: base.concat([ { v: "138 kV", n: "Linha dedicada até a planta", l: 0.4 } ]),
    a4: base.concat([
      { v: "138 kV", n: "Rede de subtransmissão", l: 0.8 },
      { v: "138 → 13,8 kV", n: "SE da distribuidora", l: 0.5 },
      { v: "13,8 kV", n: "Rede de média tensão até a planta", l: 1.6 }
    ]),
    bt: base.concat([
      { v: "138 kV", n: "Rede de subtransmissão", l: 0.8 },
      { v: "138 → 13,8 kV", n: "SE da distribuidora", l: 0.5 },
      { v: "13,8 kV", n: "Rede de média tensão", l: 1.6 },
      { v: "13,8 kV → 220 V", n: "Transformador de poste", l: 1.5 },
      { v: "220 V", n: "Rede de baixa tensão até o medidor", l: 2.9 }
    ])
  };
  function render(key){
    var steps = prof[key];
    var html = "", total = 0;
    steps.forEach(function(s){
      total += s.l;
      html += "<div class='chain-step'><div class='cs-volt'>" + s.v + "</div><div class='cs-name'>" + s.n + "</div><div class='cs-loss'>~" + String(s.l).replace(".", ",") + "% típ.</div></div>";
    });
    chainEl.innerHTML = html;
    totalEl.innerHTML = "~" + total.toFixed(1).replace(".", ",") + "<span class='unit'>%</span>";
  }
  var pills = document.querySelectorAll("#i03-pills .pill");
  pills.forEach(function(p){
    p.addEventListener("click", function(){
      pills.forEach(function(x){ x.classList.remove("active"); });
      p.classList.add("active");
      render(p.dataset.prof);
    });
  });
  render("a2");
})();

/* ============================================================
   INSTRUMENT 08: Net load curve & evening ramp
   ============================================================ */
(function(){
  var picoEl = $id("i08-pico");
  if(!picoEl) return;
  var solarEl = $id("i08-solar"), ceuEl = $id("i08-ceu");
  var svgEl = $id("i08-svg"), minOut = $id("i08-min"), rampaOut = $id("i08-rampa"), solOut = $id("i08-solpico"), verd = $id("i08-verdict");
  var f = [0.72,0.70,0.68,0.67,0.67,0.68,0.72,0.78,0.84,0.88,0.90,0.91,0.90,0.89,0.88,0.88,0.90,0.95,1.00,0.99,0.95,0.90,0.83,0.77,0.72];
  function calc(){
    var pico = parseFloat(picoEl.value) || 95;
    var S = parseFloat(solarEl.value) || 0;
    var cond = parseFloat(ceuEl.value);
    var load = [], sol = [], net = [];
    for(var h = 0; h <= 24; h++){
      var L = pico * f[h];
      var s = (h >= 6 && h <= 18) ? S * cond * Math.pow(Math.max(0, Math.sin(Math.PI * (h - 6) / 12)), 1.5) : 0;
      load.push(L); sol.push(s); net.push(L - s);
    }
    var minNet = Infinity, minH = 0, rampa = -Infinity, rH = 0;
    for(h = 0; h <= 24; h++){ if(net[h] < minNet){ minNet = net[h]; minH = h; } }
    for(h = 0; h < 24; h++){ var d = net[h+1] - net[h]; if(d > rampa){ rampa = d; rH = h; } }
    var solPico = S * cond;
    minOut.textContent = fb(minNet, 0) + " GW às " + minH + "h";
    rampaOut.textContent = "+" + fb(rampa, 1) + " GW/h (" + rH + "→" + (rH+1) + "h)";
    solOut.textContent = fb(solPico, 0) + " GW";
    var msg, cls;
    if(rampa > 10){
      cls = "verdict danger";
      msg = "<b>Rampa crítica: +" + fb(rampa,1) + " GW em uma hora.</b> É substituir uma Itaipu de geração em sessenta minutos — hidro flexível, térmicas, baterias e intercâmbios subindo juntos, com o operador contando reserva. A hora mais tensa do dia, todos os dias.";
    } else if(minNet < 35){
      cls = "verdict warn";
      msg = "<b>Carga líquida mínima muito baixa (" + fb(minNet,0) + " GW às " + minH + "h).</b> Com inflexibilidades e renovável compulsória, sobra geração no meio do dia: CMO no piso, risco de excesso e de corte de renovável — a barriga solar que antecipa a discussão de curtailment da Aula 10.";
    } else if(rampa > 6){
      cls = "verdict warn";
      msg = "<b>Rampa exigente: +" + fb(rampa,1) + " GW/h no pôr do sol.</b> Dentro da capacidade do parque flexível, mas é exatamente esta janela que valoriza bateria, resposta da demanda e a hidro com reservatório — os recursos da Aula 07.";
    } else {
      cls = "verdict";
      msg = "<b>Dia tranquilo: rampa máxima de +" + fb(rampa,1) + " GW/h.</b> Com pouca solar, a curva líquida quase coincide com a total e a transição do fim da tarde é suave. Suba a solar instalada e veja a barriga do meio-dia se formar — e a rampa ficar íngreme.";
    }
    verd.className = cls; verd.innerHTML = msg;
    var x0 = 46, x1 = 664, y0 = 14, y1 = 212;
    var ymax = pico + 5, ymin = Math.max(0, minNet - 10);
    function X(h){ return x0 + h / 24 * (x1 - x0); }
    function Y(v){ return y0 + (ymax - v) / (ymax - ymin) * (y1 - y0); }
    var mono = "font-family='JetBrains Mono, monospace' font-size='10'";
    var svg = "";
    svg += "<line x1='" + x0 + "' y1='" + y1 + "' x2='" + x1 + "' y2='" + y1 + "' stroke='rgba(255,255,255,0.12)'/>";
    [6, 12, 18].forEach(function(hh){
      svg += "<line x1='" + X(hh) + "' y1='" + y0 + "' x2='" + X(hh) + "' y2='" + y1 + "' stroke='rgba(255,255,255,0.07)' stroke-dasharray='2 5'/>";
    });
    [0, 6, 12, 18, 24].forEach(function(hh){
      svg += "<text x='" + X(hh) + "' y='" + (y1 + 16) + "' text-anchor='middle' fill='rgba(255,255,255,0.35)' " + mono + ">" + hh + "h</text>";
    });
    var pTot = [], pNet = [];
    for(h = 0; h <= 24; h++){ pTot.push(X(h).toFixed(1) + "," + Y(load[h]).toFixed(1)); pNet.push(X(h).toFixed(1) + "," + Y(net[h]).toFixed(1)); }
    svg += "<polyline points='" + pTot.join(" ") + "' fill='none' stroke='var(--cyan)' stroke-width='2' stroke-opacity='0.85'/>";
    svg += "<polyline points='" + pNet.join(" ") + "' fill='none' stroke='var(--gold)' stroke-width='2'/>";
    svg += "<circle cx='" + X(minH) + "' cy='" + Y(minNet) + "' r='3.5' fill='var(--gold)'/>";
    svg += "<text x='" + (x0 + 4) + "' y='" + (y0 + 10) + "' fill='var(--cyan)' " + mono + ">Carga total</text>";
    svg += "<text x='" + (x0 + 4) + "' y='" + (y0 + 24) + "' fill='var(--gold)' " + mono + ">Carga líquida</text>";
    svgEl.innerHTML = svg;
  }
  bindIR("i08-pico", calc);
  bindIR("i08-solar", calc);
  ceuEl.addEventListener("input", calc);
  calc();
})();

/* ============================================================
   INSTRUMENT 04: Merit-order dispatch
   ============================================================ */
(function(){
  var demEl = $id("i04-dem");
  if(!demEl) return;
  var ventoEl = $id("i04-vento"), solEl = $id("i04-sol"), resEl = $id("i04-res");
  var stackEl = $id("i04-stack"), cmoOut = $id("i04-cmo"), margOut = $id("i04-marg"), termOut = $id("i04-term"), cutOut = $id("i04-cut"), verd = $id("i04-verdict");
  var PISO = 61;
  function plantList(v, s, r){
    var va = Math.max(PISO, Math.min(650, Math.round(650 - 6.2 * r)));
    return [
      { id: "hfio", name: "Hidro fio d'água", cap: 13, cost: 1, cls: "hidro-fio", must: true, ctxt: "must-run" },
      { id: "eol", name: "Eólica", cap: 22 * v / 100, cost: 0, cls: "eolica", must: true, ctxt: "must-run" },
      { id: "sol", name: "Solar (UFV + MMGD)", cap: 25 * s / 100, cost: 0, cls: "solar", must: true, ctxt: "must-run" },
      { id: "nuc", name: "Nuclear", cap: 2, cost: 30, cls: "nuclear", must: true, ctxt: "R$ 30" },
      { id: "hres", name: "Hidro reservatório", cap: 42, cost: va, cls: "hidro-res", must: false, ctxt: "R$ " + va + " · valor da água" },
      { id: "gn1", name: "GN eficiente", cap: 9, cost: 190, cls: "gas", must: false, ctxt: "R$ 190" },
      { id: "car", name: "Carvão", cap: 2.5, cost: 280, cls: "carvao", must: false, ctxt: "R$ 280" },
      { id: "gn2", name: "GN flexível", cap: 9, cost: 340, cls: "gas", must: false, ctxt: "R$ 340" },
      { id: "ole", name: "Óleo / diesel", cap: 4.5, cost: 950, cls: "oleo", must: false, ctxt: "R$ 950" },
      { id: "gnl", name: "GNL spot / importação", cap: 3, cost: 1200, cls: "oleo", must: false, ctxt: "R$ 1.200" }
    ];
  }
  function g(x){ return x.toFixed(1).replace(".", ","); }
  function calc(){
    var D = parseFloat(demEl.value) || 0;
    var v = parseFloat(ventoEl.value) || 0;
    var s = parseFloat(solEl.value) || 0;
    var r = parseFloat(resEl.value) || 0;
    var ps = plantList(v, s, r).sort(function(a, b){ return a.cost - b.cost; });
    var byId = {};
    ps.forEach(function(p){ byId[p.id] = p; });
    var mustCap = 0;
    ps.forEach(function(p){ if(p.must) mustCap += p.cap; });
    var disp = {}, marg = null, cut = 0, deficit = 0, cmo;
    if(D <= mustCap){
      var excess = mustCap - D;
      ps.forEach(function(p){ disp[p.id] = p.must ? p.cap : 0; });
      var cs = Math.min(excess, byId["sol"].cap); disp["sol"] -= cs; excess -= cs;
      var ce = Math.min(excess, byId["eol"].cap); disp["eol"] -= ce; excess -= ce;
      var ch = Math.min(excess, byId["hfio"].cap); disp["hfio"] -= ch; excess -= ch;
      cut = cs + ce + ch;
      cmo = PISO;
    } else {
      var rem = D;
      ps.forEach(function(p){
        var dd = Math.min(p.cap, rem);
        disp[p.id] = dd;
        if(dd > 1e-9) marg = p;
        rem -= dd;
      });
      deficit = rem > 1e-6 ? rem : 0;
      cmo = marg ? Math.max(PISO, marg.cost) : PISO;
    }
    var html = "";
    ps.forEach(function(p){
      var dGW = disp[p.id] || 0;
      var isMarg = marg && p.id === marg.id;
      var pf = p.cap > 0 ? dGW / p.cap * 100 : 0;
      html += "<div class='d-row" + (isMarg ? " marginal" : "") + (dGW <= 1e-9 ? " off" : "") + "'>"
            + "<div class='d-name'>" + p.name + "</div>"
            + "<div class='d-track'><div class='d-fill " + p.cls + "' style='width:" + pf.toFixed(1) + "%'></div></div>"
            + "<div class='d-val'>" + g(dGW) + " / " + g(p.cap) + " GW · " + p.ctxt + "</div></div>";
    });
    stackEl.innerHTML = html;
    cmoOut.textContent = "R$ " + cmo;
    margOut.textContent = deficit > 0 ? "Pilha esgotada" : (marg ? marg.name : "— · piso (excedente renovável)");
    var term = (disp["gn1"] || 0) + (disp["car"] || 0) + (disp["gn2"] || 0) + (disp["ole"] || 0) + (disp["gnl"] || 0);
    termOut.textContent = g(term) + " GW";
    cutOut.textContent = g(cut) + " GW";
    if(deficit > 0){
      verd.className = "verdict danger";
      verd.innerHTML = "<b>Déficit de " + g(deficit) + " GW — a pilha esgotou.</b> No mundo real isso é corte de carga: ERAC, racionamento, manchete. Note o caminho até aqui: cada GW extra de demanda subiu degraus cada vez mais caros antes de faltar.";
    } else if(cut > 0){
      verd.className = "verdict warn";
      verd.innerHTML = "<b>Excedente renovável: " + g(cut) + " GW cortados.</b> Geração compulsória maior que a demanda — CMO no piso e curtailment. É a fotografia do Nordeste em madrugada ventosa de baixa carga, e a ponte direta para a Aula 09.";
    } else if(marg && marg.id === "hres"){
      verd.className = "verdict";
      verd.innerHTML = "<b>Hidro na margem — CMO = valor da água (R$ " + marg.cost + ").</b> O estado normal do Brasil: o preço não é o custo de queimar combustível hoje, é o custo de não ter água amanhã. Mexa nos reservatórios e veja o preço inteiro se deslocar.";
    } else if(marg && (marg.id === "gn1" || marg.id === "car" || marg.id === "gn2")){
      verd.className = "verdict warn";
      verd.innerHTML = "<b>Térmica na margem (R$ " + marg.cost + ").</b> Estiagem e/ou noite sem vento e sol: cada GW adicional sobe um degrau da pilha. É o regime em que bandeira tarifária e PLD sobem juntos.";
    } else if(marg && (marg.id === "ole" || marg.id === "gnl")){
      verd.className = "verdict danger";
      verd.innerHTML = "<b>Topo da pilha (R$ " + marg.cost + ").</b> Óleo e GNL na margem — padrão de crise hídrica, como 2021. O sistema atende, mas a que preço: é aqui que teto de PLD e encargos viram assunto de jornal.";
    } else {
      verd.className = "verdict";
      verd.innerHTML = "<b>Renovável e nuclear cobrem a carga.</b> CMO no piso — condição de demanda muito baixa com oferta compulsória abundante.";
    }
  }
  bindIR("i04-dem", calc);
  bindIR("i04-vento", calc);
  bindIR("i04-sol", calc);
  bindIR("i04-res", calc);
  calc();
})();

/* ============================================================
   INSTRUMENT 09: Battery MW x MWh
   ============================================================ */
(function(){
  var mwEl = $id("i09-mw");
  if(!mwEl) return;
  var mwhEl = $id("i09-mwh");
  var hOut = $id("i09-h"), vocOut = $id("i09-voc"), verd = $id("i09-verdict");
  function calc(){
    var P = parseFloat(mwEl.value) || 1;
    var E = parseFloat(mwhEl.value) || 0;
    var h = E / P;
    hOut.textContent = fb(h, 1) + " h";
    var voc;
    if(h < 1) voc = "Regulação rápida · serviços ancilares";
    else if(h <= 3) voc = "Corte de pico · arbitragem curta";
    else voc = "Rampa do fim da tarde · deslocamento de energia";
    vocOut.textContent = voc;
    if(h < 1){
      verd.className = "verdict warn";
      verd.innerHTML = "<b>Tanque curto (" + fb(h,1) + " h): potência sem fôlego.</b> Vocação para resposta rápida — frequência, suavização — não para atravessar o pico. E o princípio de sempre: <b>bateria não gera, desloca</b> — ela só vale o spread entre a energia que a carrega e a que ela substitui.";
    } else if(h <= 3){
      verd.className = "verdict";
      verd.innerHTML = "<b>" + fb(h,1) + " horas na potência máxima.</b> O formato clássico para cortar pico de demanda e arbitrar as horas caras. Lembre: bateria não gera — desloca energia do horário em que sobra para o horário em que falta.";
    } else {
      verd.className = "verdict";
      verd.innerHTML = "<b>" + fb(h,1) + " horas de fôlego: perfil de rampa.</b> Carrega na barriga solar do meio-dia e descarrega das 17h às 21h — exatamente a janela do INST·04. É a logística temporal que a curva líquida pede; geração, que é bom, continua vindo de quem converte fonte primária.";
    }
  }
  bindIR("i09-mw", calc);
  bindIR("i09-mwh", calc);
  calc();
})();

/* ============================================================
   INSTRUMENT 05: Frequency excursion (SVG)
   ============================================================ */
(function(){
  var dpEl = $id("i05-dp");
  if(!dpEl) return;
  var cargaEl = $id("i05-carga"), hEl = $id("i05-h");
  var svgEl = $id("i05-svg"), rocofOut = $id("i05-rocof"), nadirOut = $id("i05-nadir"), statusOut = $id("i05-status"), verd = $id("i05-verdict");
  function calc(){
    var DP = parseFloat(dpEl.value) || 0;
    var P = parseFloat(cargaEl.value) || 1;
    var H = parseFloat(hEl.value);
    var rocof = (DP / P) * 60 / (2 * H);
    var dfn = (DP / P) * 60 * 1.8 / (2 * H);
    var nadir = 60 - dfn;
    rocofOut.textContent = "−" + fb(rocof, 2) + " Hz/s";
    nadirOut.textContent = fb(nadir, 2) + " Hz";
    var st;
    if(nadir < 57.5){
      st = "Colapso parcial";
      verd.className = "verdict danger";
      verd.innerHTML = "<b>Nadir abaixo de 57,5 Hz.</b> Múltiplos estágios de ERAC e risco de colapso parcial — milhões de consumidores desligados automaticamente para salvar o restante. Compare com a noite de Itaipu, 2009.";
    } else if(nadir < 58.5){
      st = "ERAC dispara";
      verd.className = "verdict danger";
      verd.innerHTML = "<b>ERAC dispara.</b> O afundamento cruza o primeiro estágio (~58,5 Hz): blocos de carga são cortados sem nenhum humano no circuito. O sistema sobrevive sacrificando consumo — é o desenho funcionando, não falhando.";
    } else if(nadir < 59.5){
      st = "Severo, contido";
      verd.className = "verdict warn";
      verd.innerHTML = "<b>Afundamento severo, contido.</b> Inércia + regulação primária seguram o nadir acima do ERAC; a reserva foi consumida e o CAG recompõe nos minutos seguintes. Margem curta: o mesmo evento com menos inércia cruzaria a linha — troque o mix e confira.";
    } else {
      st = "Estabilizado";
      verd.className = "verdict";
      verd.innerHTML = "<b>Excursão absorvida.</b> A inércia limita o RoCoF, a regulação primária estanca a queda e o CAG devolve o sistema a 60,00 Hz. Rotina de operador — invisível para o consumidor.";
    }
    statusOut.textContent = st;
    var x0 = 46, x1 = 664, y0 = 16, y1 = 214;
    var fmax = 60.4;
    var fmin = Math.min(57.0, nadir - 0.4);
    function X(t){ return x0 + (t / 30) * (x1 - x0); }
    function Y(f){ return y0 + (fmax - f) / (fmax - fmin) * (y1 - y0); }
    var pts = [];
    for(var t = 0; t <= 30.001; t += 0.25){
      var f = 60 - dfn * (t / 5) * Math.exp(1 - t / 5);
      pts.push(X(t).toFixed(1) + "," + Y(f).toFixed(1));
    }
    var mono = "font-family='JetBrains Mono, monospace' font-size='10'";
    var svg = "";
    svg += "<line x1='" + x0 + "' y1='" + y1 + "' x2='" + x1 + "' y2='" + y1 + "' stroke='rgba(255,255,255,0.12)'/>";
    [0, 10, 20, 30].forEach(function(tt){
      svg += "<text x='" + X(tt) + "' y='" + (y1 + 16) + "' text-anchor='middle' fill='rgba(255,255,255,0.35)' " + mono + ">" + tt + " s</text>";
    });
    svg += "<line x1='" + x0 + "' y1='" + Y(60) + "' x2='" + x1 + "' y2='" + Y(60) + "' stroke='var(--cyan)' stroke-opacity='0.55' stroke-dasharray='2 5'/>";
    svg += "<text x='" + (x0 - 6) + "' y='" + (Y(60) + 3) + "' text-anchor='end' fill='var(--cyan)' " + mono + ">60</text>";
    svg += "<line x1='" + x0 + "' y1='" + Y(58.5) + "' x2='" + x1 + "' y2='" + Y(58.5) + "' stroke='var(--red)' stroke-opacity='0.7' stroke-dasharray='5 4'/>";
    svg += "<text x='" + (x0 + 4) + "' y='" + (Y(58.5) - 5) + "' fill='var(--red)' " + mono + ">ERAC · 58,5 Hz</text>";
    svg += "<polyline points='" + pts.join(" ") + "' fill='none' stroke='var(--gold)' stroke-width='2'/>";
    svg += "<circle cx='" + X(5) + "' cy='" + Y(nadir) + "' r='3.5' fill='var(--gold)'/>";
    svg += "<text x='" + (X(5) + 8) + "' y='" + (Y(nadir) + 13) + "' fill='var(--gold)' " + mono + ">" + fb(nadir, 2) + " Hz</text>";
    svgEl.innerHTML = svg;
  }
  bindIR("i05-dp", calc);
  bindIR("i05-carga", calc);
  hEl.addEventListener("input", calc);
  calc();
})();

/* ============================================================
   INSTRUMENT 06: Embedded loss cost
   ============================================================ */
(function(){
  var c = $id("i06-c");
  if(!c) return;
  var p = $id("i06-p"), t = $id("i06-t");
  var injOut = $id("i06-inj"), perdOut = $id("i06-perd"), rsOut = $id("i06-rs");
  function calc(){
    var C = parseFloat(c.value) || 0;
    var P = (parseFloat(p.value) || 0) / 100;
    var T = parseFloat(t.value) || 0;
    var inj = P < 1 ? C / (1 - P) : C;
    var perd = inj - C;
    var custo = perd * T;
    injOut.textContent = fb(inj, 0) + " MWh";
    perdOut.textContent = fb(perd, 1) + " MWh";
    rsOut.textContent = custo >= 1e6 ? "R$ " + fb(custo / 1e6, 2) + " mi" : "R$ " + fb(custo / 1000, 1) + " mil";
  }
  bindIR("i06-c", calc);
  bindIR("i06-p", calc);
  bindIR("i06-t", calc);
  calc();
})();

/* ============================================================
   INSTRUMENT 07: Two submarkets, one wire
   ============================================================ */
(function(){
  var ventoEl = $id("i07-vento");
  if(!ventoEl) return;
  var dseEl = $id("i07-dse"), limEl = $id("i07-lim");
  var neOut = $id("i07-ne"), seOut = $id("i07-se"), flowOut = $id("i07-flow"), cutOut = $id("i07-cut"), verd = $id("i07-verdict");
  var PISO = 61, DNE = 12;
  function dispatchIsland(stack, dem){
    var rem = dem, marg = null, disp = [];
    for(var i = 0; i < stack.length; i++){
      var d = Math.min(stack[i].cap, Math.max(0, rem));
      disp.push(d);
      if(d > 1e-9) marg = stack[i];
      rem -= d;
    }
    return { disp: disp, marg: marg, rem: rem };
  }
  function g(x){ return x.toFixed(1).replace(".", ","); }
  function calc(){
    var W = parseFloat(ventoEl.value) || 0;
    var DSE = parseFloat(dseEl.value) || 0;
    var L = parseFloat(limEl.value) || 0;
    var joint = [
      { cap: W, cost: 0 },
      { cap: 38, cost: 160 },
      { cap: 14, cost: 360 },
      { cap: 8, cost: 480 },
      { cap: 99, cost: 980 }
    ];
    var rj = dispatchIsland(joint, DNE + DSE);
    var genNE = rj.disp[0] + rj.disp[3];
    var flow = genNE - DNE;
    var pne, pse, cut, sat, f;
    if(Math.abs(flow) <= L + 1e-9){
      f = flow; sat = false;
      pne = pse = Math.max(PISO, rj.marg.cost);
      cut = W - rj.disp[0];
    } else {
      sat = true;
      f = flow > 0 ? L : -L;
      var demNE = Math.max(0, DNE + f);
      if(demNE <= W + 1e-9){
        cut = W - demNE;
        pne = PISO;
      } else {
        cut = 0;
        var tneed = demNE - W;
        pne = tneed <= 8 + 1e-9 ? 480 : 980;
      }
      var rse = dispatchIsland([{ cap: 38, cost: 160 }, { cap: 14, cost: 360 }, { cap: 99, cost: 980 }], DSE - f);
      pse = Math.max(PISO, rse.marg.cost);
    }
    neOut.textContent = "R$ " + pne;
    seOut.textContent = "R$ " + pse;
    flowOut.textContent = g(f) + " / " + g(L) + " GW · " + (sat ? "SATURADO" : "com folga");
    cutOut.textContent = g(cut) + " GW";
    if(!sat){
      verd.className = "verdict";
      verd.innerHTML = "<b>Intercâmbio com folga: preço único.</b> A usina marginal de um lado precifica os dois — os submercados se comportam como um sistema só. É o regime em que o spread NE–SE do Brazil Pulse marca zero.";
    } else if(cut > 1e-9){
      verd.className = "verdict danger";
      verd.innerHTML = "<b>Fio cheio + vento sobrando: " + g(cut) + " GW cortados no NE</b> enquanto o SE despacha térmica a R$ " + pse + ". Os preços se separam (spread de R$ " + (pse - pne) + "), o gerador eólico perde receita e a disputa do constrained-off entra em cena. Este é o paradoxo que abre qualquer conversa de Summit.";
    } else if(f > 0){
      verd.className = "verdict warn";
      verd.innerHTML = "<b>Intercâmbio saturado: submercados separados.</b> O NE exporta no limite físico; o SE completa com geração própria mais cara. O spread de PLD (R$ " + (pse - pne) + ") é o preço visível do congestionamento — a restrição física virando número que qualquer agente enxerga na tela.";
    } else {
      verd.className = "verdict warn";
      verd.innerHTML = "<b>Vento fraco: o NE importa até o limite.</b> Com o fio saturado no sentido contrário, é o NE que fica caro (térmica local a R$ " + pne + ") enquanto o SE segue mais barato. Congestionamento não tem lado fixo — tem a direção do dia.";
    }
  }
  bindIR("i07-vento", calc);
  bindIR("i07-dse", calc);
  bindIR("i07-lim", calc);
  calc();
})();
